"""QLoRA fine-tuning via Unsloth for local model distillation.

Dependencies: pip install -e '.[distill]'  (alpha; PyPI publish tracked at
              https://github.com/kytheros/strata-py/issues/1)
Requires: GPU with CUDA support (or Apple Silicon with MPS)
"""

import time
from pathlib import Path
from dataclasses import dataclass, field

# Allowlist of approved base models for fine-tuning.
# Only HuggingFace repos from trusted organizations are permitted.
# This prevents config injection attacks that could download arbitrary code.
APPROVED_BASE_MODELS = frozenset({
    "Qwen/Qwen2.5-3B-Instruct",
    "Qwen/Qwen2.5-7B-Instruct",
    "Qwen/Qwen2.5-14B-Instruct",
    "Qwen/Qwen3-8B",
    "meta-llama/Llama-3.1-8B-Instruct",
    "meta-llama/Llama-3.2-3B-Instruct",
    "mistralai/Mistral-7B-Instruct-v0.3",
    "google/gemma-2-9b-it",
    # Gemma 3 (March 2025) — recommended base for Strata distillation.
    "google/gemma-3-1b-it",
    "google/gemma-3-4b-it",
    "google/gemma-3-12b-it",
    "google/gemma-3-27b-it",
    # Gemma 3n edge variants (match Ollama gemma4:e2b / gemma4:e4b tags).
    "google/gemma-3n-E2B-it",
    "google/gemma-3n-E4B-it",
})


@dataclass
class TrainConfig:
    """Training configuration loaded from finetune_config.yaml."""

    base_model: str = "Qwen/Qwen2.5-7B-Instruct"
    quantization: str = "4bit"
    lora_rank: int = 16
    lora_alpha: int = 32
    lora_dropout: float = 0.05
    lora_target_modules: list[str] = field(default_factory=lambda: [
        "q_proj", "k_proj", "v_proj", "o_proj",
        "gate_proj", "up_proj", "down_proj",
    ])
    epochs: int = 3
    learning_rate: float = 2e-4
    lr_schedule: str = "cosine"
    warmup_ratio: float = 0.05
    batch_size: int = 4
    gradient_accumulation_steps: int = 2
    max_seq_length: int = 2048
    packing: bool = True
    bf16: bool = True
    output_dir: str = "~/.strata/models"
    output_format: str = "gguf"
    output_quantization: str = "Q4_K_M"


@dataclass
class TrainResult:
    """Result from a training run."""

    model_path: Path
    train_loss: float
    train_time_seconds: float
    num_examples: int
    config: TrainConfig


def load_config(config_path: str | Path) -> TrainConfig:
    """Load training config from YAML file.

    Reads the finetune_config.yaml format used by the AutoResearch loop.
    Falls back to TrainConfig defaults for any missing keys.

    Raises:
        ImportError: If pyyaml is not installed.
        FileNotFoundError: If config_path does not exist.
    """
    try:
        import yaml
    except ImportError:
        raise ImportError("pyyaml is required: pip install pyyaml")

    path = Path(config_path)
    if not path.exists():
        raise FileNotFoundError(f"Config not found: {path}")

    with open(path) as f:
        raw = yaml.safe_load(f)

    if not raw or not isinstance(raw, dict):
        return TrainConfig()

    lora = raw.get("lora", {})
    training = raw.get("training", {})
    output = raw.get("output", {})

    defaults = TrainConfig()
    return TrainConfig(
        base_model=raw.get("base_model", defaults.base_model),
        quantization=raw.get("quantization", defaults.quantization),
        lora_rank=lora.get("rank", defaults.lora_rank),
        lora_alpha=lora.get("alpha", defaults.lora_alpha),
        lora_dropout=lora.get("dropout", defaults.lora_dropout),
        lora_target_modules=lora.get("target_modules", defaults.lora_target_modules),
        epochs=training.get("epochs", defaults.epochs),
        learning_rate=training.get("learning_rate", defaults.learning_rate),
        lr_schedule=training.get("lr_schedule", defaults.lr_schedule),
        warmup_ratio=training.get("warmup_ratio", defaults.warmup_ratio),
        batch_size=training.get("per_device_train_batch_size", defaults.batch_size),
        gradient_accumulation_steps=training.get(
            "gradient_accumulation_steps", defaults.gradient_accumulation_steps
        ),
        max_seq_length=training.get("max_seq_length", defaults.max_seq_length),
        packing=training.get("packing", defaults.packing),
        bf16=training.get("bf16", defaults.bf16),
        output_dir=output.get("output_dir", defaults.output_dir),
        output_format=output.get("format", defaults.output_format),
        output_quantization=output.get("quantization", defaults.output_quantization),
    )


def train(config: TrainConfig, data_path: str | Path) -> TrainResult:
    """Run QLoRA fine-tuning using Unsloth.

    Loads the base model with 4-bit quantization, applies LoRA adapters,
    and trains on chat-template JSONL data exported by ``data.export_jsonl``.

    Args:
        config: Training configuration (from ``load_config`` or defaults).
        data_path: Path to JSONL training data (chat-template format).

    Returns:
        TrainResult with the saved model path and training metrics.

    Raises:
        ImportError: If unsloth, torch, datasets, or trl are not installed.
        FileNotFoundError: If data_path does not exist.
        RuntimeError: If no GPU is available.
    """
    # Lazy imports -- fail fast with clear messages
    try:
        from unsloth import FastLanguageModel  # type: ignore[import-untyped]
    except ImportError:
        raise ImportError(
            "Unsloth is required for training. Install with:\n"
            "  pip install -e '.[distill]'   # from source (alpha)\n"
            "  pip install 'strata-memory[distill]'   # once published to PyPI"
        )

    try:
        import torch
    except ImportError:
        raise ImportError("PyTorch is required: pip install torch")

    try:
        from datasets import load_dataset  # type: ignore[import-untyped]
    except ImportError:
        raise ImportError("datasets is required: pip install datasets")

    try:
        from trl import SFTTrainer, SFTConfig  # type: ignore[import-untyped]
    except ImportError:
        raise ImportError("trl is required: pip install trl")

    data_path = Path(data_path)
    if not data_path.exists():
        raise FileNotFoundError(f"Training data not found: {data_path}")

    # Check GPU availability
    if torch.cuda.is_available():
        device = f"cuda ({torch.cuda.get_device_name(0)})"
        print(f"GPU: {device}")
    elif hasattr(torch.backends, "mps") and torch.backends.mps.is_available():
        device = "mps (Apple Silicon)"
        print(f"GPU: {device}")
    else:
        raise RuntimeError(
            "No GPU detected. QLoRA training requires CUDA or Apple MPS.\n"
            "CPU-only training is not supported (would take days)."
        )

    output_dir = Path(config.output_dir).expanduser()
    output_dir.mkdir(parents=True, exist_ok=True)

    print(f"Loading base model: {config.base_model} ({config.quantization})")
    start_time = time.time()

    # Validate base model against allowlist (prevents arbitrary HuggingFace downloads)
    if config.base_model not in APPROVED_BASE_MODELS:
        raise ValueError(
            f"Base model '{config.base_model}' is not in the approved list.\n"
            f"Approved models: {', '.join(sorted(APPROVED_BASE_MODELS))}\n"
            f"To add a model, update APPROVED_BASE_MODELS in train.py."
        )

    # Load model with Unsloth's optimized 4-bit quantization
    model, tokenizer = FastLanguageModel.from_pretrained(
        model_name=config.base_model,
        max_seq_length=config.max_seq_length,
        load_in_4bit=(config.quantization == "4bit"),
        dtype=None,  # auto-detect
    )

    # Apply LoRA adapters
    model = FastLanguageModel.get_peft_model(
        model,
        r=config.lora_rank,
        lora_alpha=config.lora_alpha,
        lora_dropout=config.lora_dropout,
        target_modules=config.lora_target_modules,
        bias="none",
        use_gradient_checkpointing="unsloth",
    )

    # Load training data
    print(f"Loading training data from {data_path}")
    dataset = load_dataset("json", data_files=str(data_path), split="train")
    num_examples = len(dataset)
    print(f"  {num_examples} training examples loaded")

    # Format dataset for chat template
    def format_example(example: dict) -> dict:
        conversations = example.get("conversations", [])
        role_map = {"gpt": "assistant", "human": "user", "system": "system"}
        messages = [
            {
                "role": role_map.get(c["from"], c["from"]),
                "content": c["value"],
            }
            for c in conversations
        ]
        text = tokenizer.apply_chat_template(
            messages,
            tokenize=False,
            add_generation_prompt=False,
        )
        return {"text": text}

    dataset = dataset.map(format_example)

    # Configure trainer
    training_args = SFTConfig(
        output_dir=str(output_dir / "checkpoints"),
        num_train_epochs=config.epochs,
        per_device_train_batch_size=config.batch_size,
        gradient_accumulation_steps=config.gradient_accumulation_steps,
        learning_rate=config.learning_rate,
        lr_scheduler_type=config.lr_schedule,
        warmup_ratio=config.warmup_ratio,
        bf16=config.bf16,
        fp16=not config.bf16,
        logging_steps=10,
        save_strategy="epoch",
        max_seq_length=config.max_seq_length,
        packing=config.packing,
        dataset_text_field="text",
    )

    trainer = SFTTrainer(
        model=model,
        tokenizer=tokenizer,
        train_dataset=dataset,
        args=training_args,
    )

    # Train
    print(f"Starting training ({config.epochs} epochs, lr={config.learning_rate})")
    result = trainer.train()
    train_time = time.time() - start_time

    print(f"Training complete in {train_time:.0f}s. Final loss: {result.training_loss:.4f}")

    # Save the trained model
    model_name = f"strata-{data_path.stem}-{config.lora_rank}r"
    save_path = output_dir / model_name
    model.save_pretrained(str(save_path))
    tokenizer.save_pretrained(str(save_path))
    print(f"Model saved to {save_path}")

    return TrainResult(
        model_path=save_path,
        train_loss=result.training_loss,
        train_time_seconds=train_time,
        num_examples=num_examples,
        config=config,
    )
